CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', instructions text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, filename text NOT NULL, mime_type text NOT NULL, size_bytes integer NOT NULL, storage_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid REFERENCES projects(id) ON DELETE SET NULL, title text NOT NULL DEFAULT 'New conversation', model text NOT NULL DEFAULT 'openai/gpt-4o-mini', enabled_tools jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role text NOT NULL, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tool_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid REFERENCES messages(id) ON DELETE CASCADE, tool_call_id text NOT NULL, tool_name text NOT NULL, input jsonb, output jsonb, status text NOT NULL DEFAULT 'pending', started_at timestamptz, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, title text NOT NULL, url text, file_id uuid REFERENCES project_files(id) ON DELETE SET NULL, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS message_citations (message_id uuid NOT NULL REFERENCES messages(id) ON DELETE CASCADE, source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE, label text NOT NULL, PRIMARY KEY (message_id, source_id));
CREATE TABLE IF NOT EXISTS project_file_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, file_id uuid NOT NULL REFERENCES project_files(id) ON DELETE CASCADE, content text NOT NULL, page integer, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
